from fractions import Fraction as F
from math import factorial as fac,comb

def moment(p,a,n):
 return F(fac(n),fac(n//p))*a**(n//p) if n%p==0 else F(0)
def heat(poly,p,a):
 out={}
 for n,c in poly.items():
  for k in range(n//p+1):
   d=p*k
   out[n-d]=out.get(n-d,F(0))+c*F(fac(n),fac(n-d)*fac(k))*a**k
 return out
def derivative(poly,q):
 return {n-q:c*F(fac(n),fac(n-q)) for n,c in poly.items() if q<=n}
count=nonzero=0
for p in [2,4,6,8]:
 for a in [F(-1,2),F(1,3),F(-1,16)]:
  for future in [0,p,2*p]:
   future_factor=moment(p,a,future)
   for n in range(3*p+1):
    for q in range(1,p):
     P={n:future_factor}
     actual=heat(derivative(P,q),p,a).get(0,F(0))/fac(q)
     expected=comb(n,q)*moment(p,a,n-q)*future_factor if q<=n else F(0)
     assert actual==expected
     unshifted=derivative(P,q).get(0,F(0))/fac(q)
     assert (actual-unshifted==0) if n<q+p else True
     nonzero+=actual!=unshifted;count+=1
# The heat correction survives on a finite cell: it cannot be omitted exactly.
assert heat(derivative({7:F(1)},3),4,F(-1,16)).get(0)/fac(3)==F(-840,16)
assert heat(derivative({3:F(1)},3),4,F(-1,16)).get(0)/fac(3)==1
print(dict(passed=True,exact_signed_heat_jet_tests=count,nonzero_finite_cell_corrections=nonzero,
 biharmonic_septic_third_jet='-840*duration',centered_cubic_third_jet=1))
